import { useEffect, useState } from "react";
import { db, auth } from "../firebase";  // Ensure correct import path
import { doc, getDoc } from "firebase/firestore";
import {
  Button,
  Card,
  CardHeader,
  CardBody,
  NavItem,
  NavLink,
  Nav,
  Progress,
  Table,
  Container,
  Row,
  Col,
} from "reactstrap";
import Header from "components/Headers/Header.js";
import { chartOptions, parseOptions, chartExample1, chartExample2 } from "variables/charts.js";
import Chart from "chart.js";
import { Line, Bar } from "react-chartjs-2";

const Index = () => {
  const [userData, setUserData] = useState(null);
  const [activeNav, setActiveNav] = useState(1);
  const [chartData, setChartData] = useState(chartExample1.data1); // Default chart data

  useEffect(() => {
    const fetchUserData = async () => {
      if (auth.currentUser) {
        const userRef = doc(db, "users", auth.currentUser.uid);
        const userSnap = await getDoc(userRef);
        if (userSnap.exists()) {
          const data = userSnap.data();
          setUserData(data);

          // Update chart data dynamically
          setChartData({
            labels: ["Week 1", "Week 2", "Week 3", "Week 4"],
            datasets: [
              {
                label: "CO₂ Emissions",
                data: data.emissions || [0, 0, 0, 0], // Default if empty
                backgroundColor: "rgba(255, 99, 132, 0.2)",
                borderColor: "rgba(255, 99, 132, 1)",
                borderWidth: 2,
              },
            ],
          });
        }
      }
    };
    fetchUserData();
  }, []);

  if (window.Chart) {
    parseOptions(Chart, chartOptions());
  }

  const toggleNavs = (e, index) => {
    e.preventDefault();
    setActiveNav(index);
  };

  return (
    <>
      <Header />
      <Container className="mt--7" fluid>
        <Row>
          <Col className="mb-5 mb-xl-0" xl="8">
            <Card className="bg-gradient-default shadow">
              <CardHeader className="bg-transparent">
                <Row className="align-items-center">
                  <div className="col">
                    <h6 className="text-uppercase text-light ls-1 mb-1">Overview</h6>
                    <h2 className="text-white mb-0">Carbon Emissions Over Time</h2>
                  </div>
                  <div className="col">
                    <Nav className="justify-content-end" pills>
                      <NavItem>
                        <NavLink
                          className={activeNav === 1 ? "active" : ""}
                          onClick={(e) => toggleNavs(e, 1)}
                        >
                          Month
                        </NavLink>
                      </NavItem>
                      <NavItem>
                        <NavLink
                          className={activeNav === 2 ? "active" : ""}
                          onClick={(e) => toggleNavs(e, 2)}
                        >
                          Week
                        </NavLink>
                      </NavItem>
                    </Nav>
                  </div>
                </Row>
              </CardHeader>
              <CardBody>
                <div className="chart">
                  <h3 className="text-white">
                    Welcome, {userData?.name || "User"}!
                  </h3>
                  <p className="text-white">
                    Carbon Credits: {userData?.carbonCredits || 0}
                  </p>
                  <Line data={chartData} options={chartExample1.options} />
                </div>
              </CardBody>
            </Card>
          </Col>
          <Col xl="4">
            <Card className="shadow">
              <CardHeader className="bg-transparent">
                <Row className="align-items-center">
                  <div className="col">
                    <h6 className="text-uppercase text-muted ls-1 mb-1">Performance</h6>
                    <h2 className="mb-0">Emission Sources Breakdown</h2>
                  </div>
                </Row>
              </CardHeader>
              <CardBody>
                <div className="chart">
                  <Bar data={chartExample2.data} options={chartExample2.options} />
                </div>
              </CardBody>
            </Card>
          </Col>
        </Row>
      </Container>
    </>
  );
};

export default Index;
